const item = $input.first();

// Função para limpar markdown
function cleanMarkdown(text) {
  return text
    .replace(/```json\s*/g, '')
    .replace(/```\s*/g, '')
    .trim();
}

// Função para consertar JSON truncado
function fixTruncatedJSON(jsonString) {
  let fixed = jsonString.trim();

  // Conta colchetes e chaves abertas
  const openBrackets = (fixed.match(/\[/g) || []).length;
  const closeBrackets = (fixed.match(/\]/g) || []).length;
  const openBraces = (fixed.match(/\{/g) || []).length;
  const closeBraces = (fixed.match(/\}/g) || []).length;

  // Remove strings incompletas no final (que não fecham com aspas)
  // Procura pela última vírgula antes do truncamento
  const lastValidComma = fixed.lastIndexOf('",');
  const lastValidBrace = fixed.lastIndexOf('}');

  if (lastValidComma > lastValidBrace) {
    // Se tem uma vírgula após o último objeto completo, corta ali
    fixed = fixed.substring(0, lastValidComma + 1);
  } else if (lastValidBrace > 0) {
    // Se não, corta após o último objeto completo
    fixed = fixed.substring(0, lastValidBrace + 1);
  }

  // Fecha as chaves que faltam
  const bracesToClose = openBraces - closeBraces;
  const bracketsToClose = openBrackets - closeBrackets;

  for (let i = 0; i < bracesToClose; i++) {
    fixed += '\n}';
  }

  for (let i = 0; i < bracketsToClose; i++) {
    fixed += '\n]';
  }

  return fixed;
}

// Função para formatar preço
function formatPrice(price) {
  return price ? `R$ ${price.toFixed(2).replace('.', ',')}` : 'N/A';
}

try {
  // Pega o output
  let rawText = item.json.output;

  // Se for array, pega o primeiro elemento
  if (Array.isArray(item.json) && item.json.length > 0) {
    rawText = item.json[0].output;
  }

  // Limpa o markdown
  let cleanText = cleanMarkdown(rawText);

  // Tenta fazer parse direto
  let products;
  try {
    products = JSON.parse(cleanText);
  } catch (parseError) {
    // Se falhar, tenta consertar o JSON truncado
    console.log('JSON truncado detectado, tentando corrigir...');
    const fixedJSON = fixTruncatedJSON(cleanText);
    products = JSON.parse(fixedJSON);
  }

  // Garante que é um array
  if (!Array.isArray(products)) {
    products = [products];
  }

  // Filtra produtos válidos (que tenham pelo menos título ou URL)
  const validProducts = products.filter(p => p && (p.title || p.product_url || p.source_url));

  // Processa cada produto
  const processedProducts = validProducts.map((product, index) => {
    const savings = product.original_price && product.current_price 
      ? product.original_price - product.current_price 
      : 0;

    const mainImage = product.images?.[0]?.image_url || null;

    return {
      json: {
        id: `product_${index}`,
        title: product.title || 'Sem título',
        product_url: product.product_url || product.source_url,
        image_url: mainImage,
        current_price: product.current_price,
        current_price_formatted: formatPrice(product.current_price),
        original_price: product.original_price,
        original_price_formatted: formatPrice(product.original_price),
        discount_percentage: product.discount_percentage,
        savings: savings,
        savings_formatted: formatPrice(savings),
        installments: product.installments || 'Não informado',
        free_shipping: product.free_shipping || false,
        store_name: product.store_name || 'Loja não identificada',
        rating: product.rating || 0,
        reviews_count: product.reviews_count || 0,
        category: product.category,
        all_images: product.images || [],
        // Flag indicando se era o último item (pode estar incompleto)
        is_potentially_incomplete: index === validProducts.length - 1 && cleanText.includes('...truncated')
      }
    };
  });

  // Adiciona informação sobre produtos processados
  return processedProducts.length > 0 
    ? processedProducts 
    : [{ json: { 
        warning: true, 
        message: 'Nenhum produto válido encontrado',
        products_attempted: products.length 
      }}];

} catch (error) {
  // Retorna erro detalhado para debug
  return [{
    json: {
      error: true,
      message: error.message,
      error_type: error.name,
      stack: error.stack,
      raw_data_preview: String(item.json.output || item.json).substring(0, 500)
    }
  }];
}

const items = $input.all();

function parsePrice(value) {
  if (value === null || value === undefined) return 0;
  const parsed = parseFloat(value);
  return isNaN(parsed) ? 0 : parsed;
}

function parseDiscount(value) {
  if (value === null || value === undefined) return 0;
  const parsed = parseFloat(value);
  return isNaN(parsed) ? 0 : parsed;
}


const scrapedItems = items.map(item => {
  const product = item.json;

  if (product.error || product.warning) {
    return null;
  }

  return {
    title: product.title || '',
    content: product.content || product.description || null,
    source_url: product.product_url || product.source_url || '',
    current_price: parsePrice(product.current_price),
    original_price: parsePrice(product.original_price || product.current_price),
    discount_percentage: parseDiscount(product.discount_percentage),
    installments: product.installments || null,
    free_shipping: product.free_shipping === true,
    store_name: product.store_name || 'Mercado Livre',
    rating: product.rating || null,
    reviews_count: product.reviews_count || null,
    category: product.category || null,

    images: (product.all_images || []).map((img, index) => ({
      image_url: img.image_url || img.url || '',
      alt_text: img.alt_text || img.alt || product.title || '',
      display_order: index,
      is_featured: index === 0
    }))
  };
}).filter(item => item !== null);

return [{
  json: {
    scrapedItems
  }
}];
